import json
import boto3
from typing import Dict, Any

def normalize_expense_fields(extracted_text: str) -> Dict[str, Any]:
    """
    Normalizes extracted expense fields into a standard JSON schema using AWS Textract.

    Args:
        extracted_text: Raw text extracted from an expense document (e.g., receipt or invoice).

    Returns:
        A dictionary conforming to the standard expense schema:
        {
            "vendor": str,
            "date": str (ISO 8601),
            "total": float,
            "items": [
                {
                    "description": str,
                    "quantity": float,
                    "unit_price": float,
                    "amount": float
                }
            ],
            "currency": str (ISO 4217)
        }
    """
    # Initialize AWS Textract client
    textract = boto3.client('textract', region_name='us-east-1')

    # Prepare the document for Textract (assuming extracted_text is from an image or PDF)
    # In practice, you would upload the document to S3 and use its URI here
    # For this example, we simulate a document bytes object
    document_bytes = extracted_text.encode('utf-8') if isinstance(extracted_text, str) else extracted_text

    # Call AWS Textract to analyze the expense document
    response = textract.analyze_expense(
        Document={'Bytes': document_bytes}
    )

    # Initialize normalized expense data
    normalized_expense = {
        "vendor": None,
        "date": None,
        "total": None,
        "items": [],
        "currency": None
    }

    # Process Textract response to extract and normalize fields
    for expense_document in response['ExpenseDocuments']:
        for summary_field in expense_document.get('SummaryFields', []):
            field_type = summary_field['Type']['Text']

            if field_type == 'VENDOR_NAME':
                normalized_expense['vendor'] = summary_field['ValueDetection']['Text']
            elif field_type == 'INVOICE_RECEIPT_DATE':
                date_text = summary_field['ValueDetection']['Text']
                # Convert date to ISO 8601 format (simplified; adjust as needed)
                normalized_expense['date'] = date_text
            elif field_type == 'TOTAL':
                normalized_expense['total'] = float(summary_field['ValueDetection']['Text'])
            elif field_type == 'CURRENCY':
                normalized_expense['currency'] = summary_field['ValueDetection']['Text']

        for line_item_group in expense_document.get('LineItemGroups', []):
            for line_items in line_item_group['LineItems']:
                item = {
                    "description": None,
                    "quantity": 1.0,  # Default if not specified
                    "unit_price": None,
                    "amount": None
                }
                for line_item_field in line_items['LineItemExpenseFields']:
                    field_type = line_item_field['Type']['Text']
                    if field_type == 'ITEM':
                        item['description'] = line_item_field['ValueDetection']['Text']
                    elif field_type == 'PRICE':
                        item['unit_price'] = float(line_item_field['ValueDetection']['Text'])
                    elif field_type == 'QUANTITY':
                        item['quantity'] = float(line_item_field['ValueDetection']['Text'])
                    elif field_type == 'AMOUNT':
                        item['amount'] = float(line_item_field['ValueDetection']['Text'])

                if item['description']:  # Only add if description is present
                    normalized_expense['items'].append(item)

    return normalized_expense
